"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["25972"],{36737(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.calendario_dias_uteis.dia_nao_util_nulo","status":422,"titulo":"Item de dia n\xe3o \xfatil n\xe3o pode ser nulo"},"descricao":{"codigo":"uniplus.configuracao.calendario_dias_uteis.dia_nao_util_nulo","requisitos":[],"oQueAconteceu":["A opera\xe7\xe3o foi recusada porque um dos itens da lista de dias n\xe3o \xfateis veio\\n**nulo** \u2014 a lista em si foi enviada, mas um de seus elementos n\xe3o \xe9 um dia\\nn\xe3o \xfatil v\xe1lido. O erro aponta o item em `diasNaoUteis[i]`.","A valida\xe7\xe3o percorre a lista inteira: cada item nulo gera o seu erro, e os\\ndemais itens continuam sendo conferidos.","Na inclus\xe3o de um dia n\xe3o \xfatil avulso, o dia \xe9 o pr\xf3prio corpo da requisi\xe7\xe3o\\n(`item`). Um corpo **ausente** (sem conte\xfado) ou o documento JSON `null` chegam\\n\xe0 API como dia nulo: o par\xe2metro do corpo \xe9 opcional, ent\xe3o a leitura da\\nrequisi\xe7\xe3o n\xe3o os recusa e esta \xe9 a resposta (422), com o erro apontando\\n`item`. A recusa vem depois da busca do calend\xe1rio: com um identificador que n\xe3o\\nresolve, a resposta \xe9 [a de calend\xe1rio n\xe3o encontrado](/erros/uniplus.configuracao.calendario_dias_uteis.nao_encontrado).","Um corpo que chega malformado ou em formato incompat\xedvel \xe9 outro caso: recebe\\n[a recusa de requisi\xe7\xe3o malformada](/erros/uniplus.requisicao.malformada) (400)."],"comoResolver":["Na cria\xe7\xe3o, revise a lista enviada e remova ou preencha o item nulo. Na\\ninclus\xe3o avulsa, envie no corpo o dia n\xe3o \xfatil. Cada dia precisa trazer\\nabrang\xeancia, data e descri\xe7\xe3o."],"ondeAparece":["Cria\xe7\xe3o de um calend\xe1rio de dias \xfateis","Inclus\xe3o de um dia n\xe3o \xfatil avulso"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Calendario dias uteis"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"418da40321f5e48caae8956b248f9336904d661a"}}')}}]);